CREATE DATABASE IF NOT EXISTS library_inventory CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_inventory;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,checkouts,acquisitions,books,categories,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('administrator','librarian','staff') NOT NULL DEFAULT 'staff',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT) ENGINE=InnoDB;
CREATE TABLE books(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(40) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,author VARCHAR(180) NOT NULL,category_id INT UNSIGNED,quantity INT UNSIGNED NOT NULL DEFAULT 1,available_quantity INT UNSIGNED NOT NULL DEFAULT 1,classification VARCHAR(80),publisher VARCHAR(180),publication_year SMALLINT,acquired_at DATE,condition_status ENUM('good','fair','damaged','lost') NOT NULL DEFAULT 'good',description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_book_title(title),INDEX idx_book_author(author),CONSTRAINT fk_book_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE acquisitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,supplier VARCHAR(180),quantity INT UNSIGNED NOT NULL,unit_cost DECIMAL(10,2) DEFAULT 0,acquired_at DATE NOT NULL,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_acq_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE checkouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,borrower_name VARCHAR(150) NOT NULL,borrower_id VARCHAR(60) NOT NULL,checked_out_at DATETIME DEFAULT CURRENT_TIMESTAMP,due_date DATE NOT NULL,returned_at DATETIME,status ENUM('checked_out','returned','lost','damaged') NOT NULL DEFAULT 'checked_out',fine DECIMAL(10,2) NOT NULL DEFAULT 0,notes TEXT,CONSTRAINT fk_checkout_book FOREIGN KEY(book_id) REFERENCES books(id),CONSTRAINT fk_checkout_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED,action VARCHAR(120) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,requester_name VARCHAR(150) NOT NULL,requester_id VARCHAR(60) NOT NULL,contact VARCHAR(190),reserved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('pending','fulfilled','cancelled') NOT NULL DEFAULT 'pending',CONSTRAINT fk_reserve_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE stock_checks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,expected_quantity INT UNSIGNED NOT NULL,counted_quantity INT UNSIGNED NOT NULL,difference INT NOT NULL,checked_by INT UNSIGNED NOT NULL,checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,notes TEXT,CONSTRAINT fk_stock_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE,CONSTRAINT fk_stock_user FOREIGN KEY(checked_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
